 body=f'''<div class="breadcrumbs section-wrap"><a href="/">Home</a><span>/</span><a href="/shop/">Collection</a><span>/</span>{p['name']}</div><section class="product-detail section-wrap"><div class="detail-image"><img src="/assets/{p['image']}" alt="{esc(p['alt'])}" width="640" height="1136" fetchpriority="high"><span>Representative product photograph</span></div><div class="detail-copy"><span class="eyebrow">{p['categoryName']} · THE BARAKAH COLLECTION</span><h1>{p['name']}</h1><p class="detail-subtitle">{p['subtitle']}</p><p>{p['description']}</p><div class="inline-pack" data-product-id="{p['id']}"></div><div class="product-details"><details open><summary>Storage & care <span>+</span></summary><p>{p['storage']}</p></details><details><summary>Allergen information <span>+</span></summary><p>{p['allergens']} Confirm ingredients and packing details with Shakir before purchasing if you have an allergy.</p></details><details><summary>Delivery & ordering <span>+</span></summary><p>Delivery enquiries welcome across India. Share your PIN code on WhatsApp to confirm availability, shipping, and the final amount before paying.</p></details></div></div></section><div class="section-wrap">{actual_gallery(p)}</div><section class="section-wrap related"><div class="section-heading"><div><span class="eyebrow">A LITTLE MORE GOODNESS</span><h2>Meet your next favourites.</h2></div><a class="text-link" href="/shop/">Explore all {icon('arrow')}</a></div><div class="product-grid">{''.join(card(x) for x in products if x['id']!=p['id'])}</div></section>'''
