write('/about/','Meet Iflak Bhat & Shakir Nazir | Barakah Dryfruits','Meet Barakah Dryfruits, founded by Shakir Nazir with Iflak Bhat, Co-founder and CEO. Explore our dry-fruit and saffron collection and order directly with a personal conversation.',f'<section class="page-intro section-wrap"><span class="eyebrow">HELLO, WE ARE BARAKAH</span><h1>A little barakah.<br><em>In every day.</em></h1><p>A collection of little pleasures, and a person behind every order.</p></section>'+story+f'<section class="reading-section section-wrap"><h2>From our collection to your kitchen.</h2><p>Our Instagram bio introduces dry fruits, saffron and honey, alongside perfumes, attars, and car and room sprays. Browse dry fruits here, or ask Shakir about other products. Original product photos appear inside the product pages. Our homepage and collection covers use representative stock photography. Confirm current product appearance and packaging with Shakir before ordering.</p><h2>Meet the people behind Barakah.</h2><p>Founded by Shakir Nazir, with Iflak Bhat as Co-founder and CEO, Barakah Dryfruits brings everyday favourites to your table. Follow them on Instagram, or contact Shakir directly for orders.</p>{social_links()}<h2>Your portion. Your conversation.</h2><p>You might need a small pack for home, a larger quantity for the family, or a gift for someone special. Choose a standard pack or enter your preferred weight. Shakir will confirm the product variety, current price, availability, and delivery with you before you order.</p><a class="button" href="/shop/">Find your favourites {icon("arrow")}</a></section>')

write('/contact/','Contact & WhatsApp Orders | Barakah Dryfruits','Contact Barakah Dryfruits on +91 7889826963. Enquire about products, custom pack sizes, gifts, bulk quantities and delivery across India.',f'''<section class="page-intro section-wrap"><span class="eyebrow">LET'S TALK GOODNESS</span><h1>Your next order<br>starts with <em>hello.</em></h1><p>Shakir is here to help with your next handful of goodness.</p></section><section class="contact-section section-wrap"><div><h2>Start a conversation.</h2><a class="contact-number" href="tel:+917889826963">+91 78898 26963</a><p>Shakir Nazir · Founder, Barakah Dryfruits</p>{social_links()}<a class="social-link" href="{INSTA}" target="_blank" rel="noopener">{icon('instagram')} @barakah_dryfruit13 ↗</a><div class="contact-note">Enquiries welcome from across India. Share your delivery PIN code to confirm availability and delivery charges.</div></div><form id="enquiry-form"><label>Your name<input name="customer" autocomplete="name" required maxlength="80" placeholder="What should we call you?"></label><label>Delivery PIN code<input name="pincode" inputmode="numeric" autocomplete="postal-code" required pattern="[1-9][0-9]{{5}}" maxlength="6" placeholder="Your six-digit Indian PIN code"></label><label>What do you have in mind?<textarea name="message" required rows="4" maxlength="2000" placeholder="A product, a custom pack, a gift, or a question…"></textarea></label><button class="button" type="submit">Continue on WhatsApp {icon('arrow')}</button><p class="subtle">Your message opens in WhatsApp. You choose when to send it.</p></form></section>''')

write('/gifting/','Dry Fruit Gifts & Bulk Orders | Barakah Dryfruits','Enquire about dry fruit gifts, custom quantities and bulk orders with Barakah founder Shakir Nazir.',f'''<section class="collection-intro section-wrap"><div><span class="eyebrow">GOOD THINGS ARE BETTER SHARED</span><h1>A thoughtful gift.<br>Your personal touch.</h1><p>Family celebrations, a small thank-you, or a bigger occasion. Tell us your budget, quantity and preferred products.</p><a class="button" href="{WA}?text=Hello%20Shakir%21%20I%27d%20like%20a%20quote%20for%20dry%20fruit%20gifts%20or%20a%20bulk%20order.%20Please%20share%20available%20products%2C%20packaging%2C%20minimum%20quantities%20and%20prices." target="_blank" rel="noopener">Get a gift or bulk quote ↗</a></div><img src="/assets/web-pantry.jpg" alt="Representative nuts in a glass bowl" fetchpriority="high"></section><section class="reading-section section-wrap"><h2>Made around your occasion.</h2><p>Choose nuts, anjeer or saffron, then discuss your preferred portions and available gift packaging. Packaging, minimum quantities, availability and pricing are confirmed before an order is accepted.</p><h2>A date in mind?</h2><p>Share the delivery PIN code and date you need your order. Shakir will confirm whether delivery is possible and provide the final quote.</p><a class="text-link" href="/shop/dry-fruits/">Explore dry fruits {icon('arrow')}</a></section>''')
for slug,title,description,message in [('honey','Honey','Explore honey enquiries with Barakah. Ask Shakir about current varieties, pack sizes and prices.','Hello Shakir! I would like to enquire about honey. Please share available varieties, pack sizes, current prices and delivery details.'),('fragrances','Perfumes & attars','Barakah’s Instagram bio also lists perfumes, attars, and car and room sprays. Ask Shakir what is currently available.','Hello Shakir! I would like to enquire about perfumes, attars, or car and room sprays. Please share the available products, sizes and prices.')]:
 from urllib.parse import quote
 write('/collections/'+slug+'/',title+' Enquiries | Barakah Dryfruits',description,f'<section class="page-intro section-wrap"><span class="eyebrow">ALSO FROM BARAKAH</span><h1>{title}</h1><p>{description}</p></section><section class="reading-section section-wrap"><h2>Find out what is available.</h2><p>Varieties, product details, sizes, pricing and delivery are confirmed directly with Shakir. These products are available by enquiry rather than a fixed online catalogue.</p><a class="button" href="{WA}?text={quote(message)}" target="_blank" rel="noopener">Ask Shakir on WhatsApp ↗</a><p class="subtle">Your enquiry is prefilled. Review it and tap Send in WhatsApp.</p></section>')

policy_data={
 'shipping':('Ordering & Delivery','Made personal. Kept simple.', [('1. Choose your favourites','Browse the collection, choose a standard pack or custom weight, and use Order this pack on WhatsApp for a prefilled order request. Use Save to bag to collect several items in one bag. Listed prices are estimates; choosing a pack does not reserve stock.'),('2. Review with Shakir','Send the prefilled request in WhatsApp. We aim to confirm within 30 minutes after your message is received. Response time may vary; an order is accepted only after Shakir confirms variety, weight, availability, price, delivery and payment details.'),('3. Confirm delivery','We welcome enquiries from across India. Delivery serviceability and timing depend on the destination and are confirmed using your PIN code. No free-shipping threshold or guaranteed delivery time is promised on this website.'),('4. Payment & dispatch','Payment instructions, dispatch timing, tracking where available, and order confirmation are agreed directly on WhatsApp. This website does not collect card details or process online payments.'),('Need help?', 'Contact Shakir on +91 7889826963 with your order conversation and delivery PIN code.')]),
 'returns':('Order Support','A little help, whenever you need it.', [('A question about your order?','Please contact Shakir on WhatsApp with your name, order conversation, and a description of the issue. Include clear photos if an item is damaged, incorrect, or different from what was agreed.'),('Confirm terms before purchase','Product-specific cancellation, return, replacement, and refund arrangements are confirmed directly with Shakir before an order is accepted. This website does not promise a fixed return window or automatic refund.'),('Food & packaging','Keep the packaging and order details while an issue is being reviewed. Do not consume food if the seal is damaged or the product appears unsafe. Your applicable consumer rights are unaffected.')]),
 'privacy':('Privacy','Your details, handled thoughtfully.', [('Your shopping bag','The website saves your chosen items in your browser’s local storage so your bag remains available when you return on the same browser. You can remove items in the bag or clear your browser’s site data.'),('Enquiries & WhatsApp','The enquiry form builds a WhatsApp message in your browser. It is not sent to a website database. When you choose to continue and send the message, the information is shared with WhatsApp and Barakah Dryfruits to respond to your enquiry. WhatsApp’s own privacy terms apply.'),('External links & hosting','Instagram and WhatsApp links open their respective services. Those services and the website hosting provider may handle technical connection data under their own terms. No advertising trackers or newsletter sign-up service have been added to this website.'),('Contact','For questions about information shared with Barakah Dryfruits, contact Shakir Nazir at +91 7889826963.')])}
for slug,(name,headline,sections) in policy_data.items():
 write('/'+slug+'/',name+' | Barakah Dryfruits',name+' information for Barakah Dryfruits customers. Confirm orders, delivery and any order concerns directly with Shakir Nazir.',f'<section class="page-intro section-wrap"><span class="eyebrow">HERE TO HELP</span><h1>{name}</h1><p>{headline}</p></section><article class="reading-section section-wrap">'+''.join(f'<h2>{h}</h2><p>{t}</p>' for h,t in sections)+f'<a class="button" href="{WA}" target="_blank" rel="noopener">Talk to Shakir {icon("arrow")}</a></article>')

pages=sorted('/'+str(p.parent.relative_to(DIST)).replace('\\','/').strip('.')+'/' for p in DIST.rglob('index.html'))
pages=[re.sub('/+','/',p) for p in pages]
(DIST/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+ORIGIN+p+'</loc></url>' for p in pages)+'</urlset>')
(DIST/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+ORIGIN+'/sitemap.xml\n')
(DIST/'404.html').write_text(shell('Page Not Found | Barakah Dryfruits','Find your way back to Barakah Dryfruits.',f'<section class="page-intro section-wrap"><span class="eyebrow">A LITTLE DETOUR</span><h1>This page wandered off.</h1><p>Your next favourite is still waiting in the collection.</p><a class="button" href="/shop/">Back to the good stuff {icon("arrow")}</a></section>','/404.html'))
print(f'Built {len(pages)} pages, catalog, sitemap, and robots.txt')
